  const hojeISO = () => new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 10);
  const MESES = k => { const n = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro']; const m = parseInt(String(k).slice(5, 7)); return n[m - 1] ? n[m - 1] + (String(k).slice(0, 4) !== String(new Date().getFullYear()) ? ' ' + String(k).slice(0, 4) : '') : String(k); };
