  const contagem = (l, d) => O.S.contagens.find(c => c.lojaId === l && c.data === d);
  function lojasComDados() { return proprias().filter(l => fechadasDe(l).length); }
  function datasFechadas(l) {
    if (l === 'Todas') { const ls = lojasComDados(); if (!ls.length) return []; let inter = new Set(fechadasDe(ls[0])); for (const x of ls.slice(1)) { const s = new Set(fechadasDe(x)); inter = new Set([...inter].filter(d => s.has(d))); } return [...inter].sort(); }
    return fechadasDe(l);
  }
  function proximasDatas(l) {
    const f = datasFechadas(l); const ult = f[f.length - 1]; if (!ult) return [];
    const lim = new Date(O.HOJE + 'T00:00:00Z'); lim.setUTCMonth(lim.getUTCMonth() + 3);
    const cal = calendarioEntre(ult, lim.toISOString().slice(0, 10)).filter(d => d > ult); const out = []; for (const d of cal) { out.push(d); if (d >= O.HOJE) break; } return out;
  }
  function semanas(l) { const ds = datasFechadas(l); const todas = [...ds, ...proximasDatas(l)]; return todas.map((d, i) => ({ fim: d, ini: i ? todas[i - 1] : null, fechada: l === 'Todas' ? lojasComDados().every(x => fechadasDe(x).includes(d)) : ds.includes(d), mes: mesDe(d) })); }
  function semanaAtual(l) { return semanas(l).find(s => !s.fechada) || null; }
  function semanaDe(l, data) { return semanas(l).find(s => inP(data, s.ini, s.fim)); }
  function valorItens(itens, custosAtuais) { let t = 0; for (const [pid, it] of Object.entries(itens || {})) { const c = custosAtuais ? ((prodMap()[pid] || {}).custo || 0) : (it.custo || 0); t += sum(it.parcelas || []) * c; } return t; }
  function valorContagem(l, d) { if (l === 'Todas') return sum(proprias(), x => fechadasDe(x).includes(d) ? valorContagem(x, d) : 0); const c = contagem(l, d); return c ? valorItens(c.itens) : 0; }
  function contagemAberta(l) { return contagensDe(l).find(c => c.status === 'aberta') || null; }
  function efAberto(l) { if (l === 'Todas') return sum(proprias(), efAberto); const c = contagemAberta(l); return c ? valorItens(c.itens, true) : 0; }
  function EI(l, ini) { if (l === 'Todas') return sum(proprias(), x => EI(x, ini)); return ini ? valorContagem(l, ini) : 0; }
  const ativas = arr => arr.filter(x => x.status !== 'excluída');
  function comprasCMV(l, a, b) { if (l === 'Todas') return sum(proprias(), x => comprasCMV(x, a, b)); return sum(ativas(O.S.compras).filter(c => c.lojaId === l && c.status === 'lançada' && inP(c.data, a, b)), c => sum((c.itens || []).filter(i => catCmv(i.cat)), i => i.v)); }
