    for (const e of O.S.emprestimos) { if (['contestado', 'excluída'].includes(e.status)) continue; const v = e.qtd * e.custo;
      if (inP(e.saida, a, b)) { if (e.origem === l) t -= v; if (e.destino === l && tipoLoja(l) === 'PRÓPRIA') t += v; }
      if (e.retorno && inP(e.retorno, a, b)) { if (e.origem === l) t += v; if (e.destino === l && tipoLoja(l) === 'PRÓPRIA') t -= v; } }
